// 2. 多数据源聚合上报接口。
// fresh_chassis / fresh_watchdog：本次调用时对应源是否有**新数据到达**（由调用方
// 按真实消息到达点判定，而不是按调用周期）。只有标记为 fresh 的源才刷新时效时戳；
// deadlock/estop 不参与时效判定——estop 属一次性锁存信号（latched QoS 语义），
// 对其打点会把"发布者不再重复发送"误判为过期。
// 默认 true 保持调用即刷新的旧语义（单测/简单部署）；生产节点应传真实新鲜度。
void UpdateMultiSourceHealth(const MultiSourceHealthReport& report,
                             bool fresh_chassis = true, bool fresh_watchdog = true);

input.old_string:
void FaultSupervisor::UpdateMultiSourceHealth(const MultiSourceHealthReport& report) {
  health_seen_ = true;
  latest_report_ = report;
  // 聚合上报视为四个源同时刷新
  const auto now = std::chrono::steady_clock::now();
  last_report_time_[kSourceChassis] = now;
  last_report_time_[kSourceWatchdog] = now;
  last_report_time_[kSourceDeadlock] = now;
  last_report_time_[kSourceEstop] = now;
}

input.new_string:
void FaultSupervisor::UpdateMultiSourceHealth(const MultiSourceHealthReport& report,
                                              bool fresh_chassis, bool fresh_watchdog) {
  health_seen_ = true;
  latest_report_ = report;
  // 只对"本调用确有新数据到达"的周期性源打点（I1：调用周期 ≠ 数据到达——
  // 每 tick 无条件续命会让上游发布者死亡后的失联检测完全失效）。
  // deadlock/estop 不打点：前者随拓扑快照评估，后者是一次性锁存信号，
  // 对锁存源打点会把 latched QoS 的"不重复发送"误判为过期。
  const auto now = std::chrono::steady_clock::now();
  if (fresh_chassis) {
    last_report_time_[kSourceChassis] = now;
  }
  if (fresh_watchdog) {
    last_report_time_[kSourceWatchdog] = now;
  }
}

