16	// A7：剪除已过期的时空预约（end < now），防止历史条目在表中无限累积
17	void PruneExpiredTimeSpace(
18	    std::unordered_map<std::string, std::vector<TimeSpaceReservation>>& reservations,
19	    const std::chrono::steady_clock::time_point now) {
20	  for (auto it = reservations.begin(); it != reservations.end();) {
21	    auto& list = it->second;
22	    list.erase(std::remove_if(list.begin(), list.end(),
23	                              [now](const TimeSpaceReservation& reservation) {
24	                                return reservation.interval.end < now;
25	                              }),
26	               list.end());
27	    if (list.empty()) {
28	      it = reservations.erase(it);
29	    } else {
30	      ++it;
31	    }
32	  }
33	}
