67	std::vector<std::string> ResourceTable::BuildLockIds(
68	    const std::vector<std::string>& station_path, const bool include_intersection_locks) {
69	  std::vector<std::string> lock_ids;
70	  std::unordered_set<std::string> seen;  // 保序去重：重复节点/边只保留首次出现
71	  const auto append_once = [&lock_ids, &seen](const std::string& lock_id) {
72	    if (seen.insert(lock_id).second) {
73	      lock_ids.push_back(lock_id);
74	    }
75	  };
76	  if (include_intersection_locks) {
77	    for (const auto& station_id : station_path) {
78	      append_once(RouteNodeId(station_id));
79	    }
80	  }
81	  for (std::size_t index = 1; index < station_path.size(); ++index) {
82	    append_once(RouteEdgeId(station_path[index - 1], station_path[index]));
83	  }
84	  return lock_ids;
85	}
